INSERT INTO `ec_reviews` (`id`, `customer_id`, `customer_name`, `customer_email`, `product_id`, `star`, `comment`, `status`, `created_at`, `updated_at`, `images`) VALUES
(1, 7, NULL, NULL, 46, 1, 'The best ecommerce CMS! Excellent coding! best support service! Thank you so much..... I really like your hard work.', 'published', '2025-12-26 09:38:49', '2025-12-26 09:38:49', NULL),
(2, 5, NULL, NULL, 33, 2, 'For me the best eCommerce script on Envato at this moment: modern, clean code, a lot of great features. The customer support is great too: I always get an answer within hours!', 'published', '2025-12-26 09:38:49', '2025-12-26 09:38:49', NULL),
(3, 1, NULL, NULL, 10, 5, 'The code is good, in general, if you like it, can you give it 5 stars?', 'published', '2025-12-26 09:38:49', '2025-12-26 09:38:49', NULL),
(4, 2, NULL, NULL, 52, 5, 'This script is well coded and is super fast. The support is pretty quick. Very patient and helpful team. I strongly recommend it and they deserve more than 5 stars.', 'published', '2025-12-26 09:38:49', '2025-12-26 09:38:49', NULL),
(5, 5, NULL, NULL, 2, 1, 'As a developer I reviewed this script. This is really awesome ecommerce script. I have convinced when I noticed that it\'s built on fully WordPress concept.', 'published', '2025-12-26 09:38:49', '2025-12-26 09:38:49', NULL),
(6, 1, NULL, NULL, 2, 5, 'We have received brilliant service support and will be expanding the features with the developer. Nice product!', 'published', '2025-12-26 09:38:49', '2025-12-26 09:38:49', NULL),
(7, 4, NULL, NULL, 45, 4, 'Great E-commerce system. And much more : Wonderful Customer Support.', 'published', '2025-12-26 09:38:49', '2025-12-26 09:38:49', NULL),
(8, 7, NULL, NULL, 31, 1, 'Solution is too robust for our purpose so we didn\'t use it at the end. But I appreciate customer support during initial configuration.', 'published', '2025-12-26 09:38:49', '2025-12-26 09:38:49', NULL),
(9, 6, NULL, NULL, 21, 2, 'As a developer I reviewed this script. This is really awesome ecommerce script. I have convinced when I noticed that it\'s built on fully WordPress concept.', 'published', '2025-12-26 09:38:49', '2025-12-26 09:38:49', NULL),
