INSERT INTO `revisions` (`id`, `revisionable_type`, `revisionable_id`, `user_id`, `key`, `old_value`, `new_value`, `created_at`, `updated_at`) VALUES
(1, 'Botble\\Page\\Models\\Page', 2, 1, 'description', NULL, 'Affinity Healthcare Ltd has been a registered company in the UK since July 2009. Based in sunny Poole, Affinity Healthcare Ltd has now grown to over 150 staff and a huge 30,000sqft of warehouse space. Specialists in medical products, our relationships with suppliers and industry professionals enable us to supply high quality products you use the most at fantastically low prices.', '2026-03-22 22:39:43', '2026-03-22 22:39:43'),
(2, 'Botble\\Page\\Models\\Page', 2, 1, 'description', 'Affinity Healthcare Ltd has been a registered company in the UK since July 2009. Based in sunny Poole, Affinity Healthcare Ltd has now grown to over 150 staff and a huge 30,000sqft of warehouse space. Specialists in medical products, our relationships with suppliers and industry professionals enable us to supply high quality products you use the most at fantastically low prices.', 'Affinity Healthcare Services Ltd has been a registered company in the UK since July 2009. Based in sunny Poole, Affinity Healthcare Services Ltd has now grown to over 150 staff and a huge 30,000sqft of warehouse space. Specialists in medical products, our relationships with suppliers and industry professionals enable us to supply high quality products you use the most at fantastically low prices.', '2026-03-22 23:03:42', '2026-03-22 23:03:42'),
(3, 'Botble\\Page\\Models\\Page', 8, 1, 'description', NULL, '', '2026-03-22 23:13:38', '2026-03-22 23:13:38'),
